SELECT status, COUNT(DISTINCT monthly_fee) AS unique_statuss, SUM(CASE WHEN plan = 'enterprise' THEN monthly_fee ELSE 0 END) AS enterprise_monthly_fee, AVG(monthly_fee) AS avg_monthly_fee FROM subscriptions WHERE status NOT IN ('EXPIRED', 'ACTIVE') AND start_date BETWEEN '2023-04-02' AND '2025-02-02' AND status IN ('EXPIRED', 'PAUSED', 'ACTIVE') GROUP BY status HAVING SUM(CASE WHEN plan = 'enterprise' THEN monthly_fee ELSE 0 END) >= 56 ORDER BY unique_statuss DESC;
